
# ============================================================
# IT3081 - STATISTICAL MODELLING
# TASK 5 & TASK 8 - SIX-MODEL COMPARISON VISUALIZATIONS
# Project: Loan Default Risk Analysis
# ============================================================

# ============================================================
# 1. LOAD SIX-MODEL COMPARISON RESULTS
# ============================================================

# The CSV is generated by scripts/08_naive_bayes.R

csv_path <- "results/task5_six_model_comparison.csv"

if (!file.exists(csv_path)) {
  stop(
    "Six-model comparison CSV not found. ",
    "Run source('scripts/08_naive_bayes.R') first."
  )
}

results <- read.csv(
  csv_path,
  stringsAsFactors = FALSE
)

# Validate required columns
required_columns <- c(
  "Model",
  "F1",
  "ROC_AUC",
  "Precision",
  "Recall"
)

if (!all(required_columns %in% names(results))) {
  stop("Required columns are missing from the CSV file.")
}

if (nrow(results) != 6) {
  stop("Expected exactly six model results.")
}

# Create output directory
output_dir <- "results/figures"

dir.create(
  output_dir,
  recursive = TRUE,
  showWarnings = FALSE
)

# ============================================================
# 2. FORMAT MODEL NAMES
# ============================================================

# Short labels with line breaks prevent overlapping text.

label_lookup <- c(
  "Naive Bayes" = "Naive\nBayes",
  "Weighted Logistic" = "Weighted\nLogistic",
  "SMOTE Logistic" = "SMOTE\nLogistic",
  "Baseline Logistic" = "Baseline\nLogistic",
  "LASSO Logistic" = "LASSO\nLogistic",
  "Ridge Logistic" = "Ridge\nLogistic"
)

model_names <- unname(
  label_lookup[results$Model]
)

if (anyNA(model_names)) {
  stop("Unknown model name found in the CSV.")
}

# Preserve ranking based on validation F1.
# The CSV generated by Task 8 is already ranked,
# but we sort explicitly for consistency.

results <- results[
  order(-results$Validation_F1),
]

model_names <- unname(
  label_lookup[results$Model]
)

# ============================================================
# 3. GRAPH 1 - TEST F1-SCORE COMPARISON
# ============================================================

png(
  filename = file.path(
    output_dir,
    "model_f1_comparison.png"
  ),
  width = 1800,
  height = 1050,
  res = 180
)

par(
  mar = c(7, 5, 4, 2)
)

bar_positions <- barplot(
  height = results$F1,
  names.arg = model_names,
  col = "steelblue",
  border = "white",
  ylim = c(0, 0.55),
  las = 1,
  cex.names = 0.82,
  cex.axis = 0.9,
  cex.lab = 1.1,
  ylab = "F1-Score",
  main = "Test F1-Score Comparison - Six Models"
)

text(
  x = bar_positions,
  y = results$F1 + 0.015,
  labels = sprintf("%.4f", results$F1),
  cex = 0.83
)

dev.off()

cat("Graph 1 saved: F1-score comparison\n")

# ============================================================
# 4. GRAPH 2 - TEST ROC-AUC COMPARISON
# ============================================================

png(
  filename = file.path(
    output_dir,
    "model_auc_comparison.png"
  ),
  width = 1800,
  height = 1050,
  res = 180
)

par(
  mar = c(7, 5, 4, 2)
)

bar_positions <- barplot(
  height = results$ROC_AUC,
  names.arg = model_names,
  col = "darkseagreen3",
  border = "white",
  ylim = c(0, 0.75),
  las = 1,
  cex.names = 0.82,
  cex.axis = 0.9,
  cex.lab = 1.1,
  ylab = "ROC-AUC",
  main = "Test ROC-AUC Comparison - Six Models"
)

# Reference line: random-ranking performance
abline(
  h = 0.5,
  col = "red",
  lty = 2,
  lwd = 2
)

text(
  x = bar_positions,
  y = results$ROC_AUC + 0.015,
  labels = sprintf("%.4f", results$ROC_AUC),
  cex = 0.83
)

legend(
  "topright",
  legend = "Random ranking (AUC = 0.50)",
  col = "red",
  lty = 2,
  lwd = 2,
  bty = "n",
  cex = 0.8
)

dev.off()

cat("Graph 2 saved: ROC-AUC comparison\n")

# ============================================================
# 5. GRAPH 3 - TEST PRECISION VS RECALL
# ============================================================

png(
  filename = file.path(
    output_dir,
    "precision_recall_comparison.png"
  ),
  width = 1800,
  height = 1050,
  res = 180
)

par(
  mar = c(7, 5, 4, 2)
)

metric_matrix <- rbind(
  Precision = results$Precision,
  Recall = results$Recall
)

bar_positions <- barplot(
  height = metric_matrix,
  beside = TRUE,
  names.arg = model_names,
  col = c("steelblue", "darkorange"),
  border = "white",
  ylim = c(0, 1),
  las = 1,
  cex.names = 0.82,
  cex.axis = 0.9,
  cex.lab = 1.1,
  ylab = "Score",
  main = "Test Precision vs Recall - Six Models"
)

text(
  x = bar_positions,
  y = metric_matrix + 0.025,
  labels = sprintf("%.3f", metric_matrix),
  cex = 0.75
)

legend(
  "topright",
  legend = c("Precision", "Recall"),
  fill = c("steelblue", "darkorange"),
  border = NA,
  bty = "n",
  cex = 0.9
)

dev.off()

cat("Graph 3 saved: Precision vs Recall comparison\n")

# ============================================================
# 6. PRINT SIX-MODEL SUMMARY
# ============================================================

cat("\n============================================\n")
cat("SIX-MODEL COMPARISON SUMMARY\n")
cat("============================================\n")

print(
  results[, c(
    "Model",
    "Validation_F1",
    "F1",
    "ROC_AUC",
    "Precision",
    "Recall"
  )],
  digits = 4,
  row.names = FALSE
)

cat("\nBest model by validation F1:\n")
print(results$Model[1])

# ============================================================
# 7. FINAL CONFIRMATION
# ============================================================

cat("\n============================================\n")
cat("ALL THREE GRAPHS GENERATED SUCCESSFULLY\n")
cat("============================================\n")

cat("\nSaved files:\n")

cat(
  "1. results/figures/model_f1_comparison.png\n"
)

cat(
  "2. results/figures/model_auc_comparison.png\n"
)

cat(
  "3. results/figures/precision_recall_comparison.png\n"
)

cat("\nTask 5 and Task 8 figures are ready.\n")

# NOTE:
# Naive Bayes is the highest-ranked model in the
# current exploratory six-model comparison.
#
# Model ranking is based on validation F1-score.
# The graphs show TEST-set performance.
#
# Weak ROC-AUC and high false-positive rates
# mean no model is deployment-ready.
